string repo = Path.GetFullPath(args.Length > 1 ? args[1] : Environment.CurrentDirectory);
string output = Path.GetFullPath(args.Length > 0 ? args[0] : Path.Combine(repo, ".validation", "core"));
Directory.CreateDirectory(output);
string fixtures = Path.Combine(output, "fixtures", Guid.NewGuid().ToString("N")); Directory.CreateDirectory(fixtures);
var results = new List<object>(); int failures = 0, assertions = 0, cases = 0;
void Check(bool condition, string why) { assertions++; if (!condition) throw new Exception(why); }
void Throws(Action action) { bool threw = false; try { action(); } catch { threw = true; } Check(threw, "Expected an exception"); }
void Near(double value, double expected, double tolerance = .01) => Check(Math.Abs(value - expected) <= tolerance, $"Expected {expected}, got {value}");
SongDocument Song(params NoteEvent[] notes) => new() { Title = "测试谱", Notes = notes.ToList() };
async Task Test(string name, Func<Task> action)
{
    cases++; var watch = Stopwatch.StartNew();
    try { await action(); results.Add(new { name, status = "PASS", milliseconds = watch.ElapsedMilliseconds }); Console.WriteLine("PASS " + name); }
    catch (Exception ex) { failures++; results.Add(new { name, status = "FAIL", error = ex.Message, milliseconds = watch.ElapsedMilliseconds }); Console.WriteLine("FAIL " + name + ": " + ex.Message); }
}
void Sync(string name, Action action) => Test(name, () => { action(); return Task.CompletedTask; }).GetAwaiter().GetResult();

Sync("Built-in Twinkle has quarter-note onsets and phrase-ending long notes", () => { var song = SongParser.Read(Path.Combine(repo, "Songs", "01.json")); var n = song.Notes.Take(8).ToList(); Check(n.Count == 8, "note count"); for (int i = 0; i < 7; i++) Near(n[i].StartMs, i * 625); Near(n[7].StartMs, 5000); Near(n[6].DurationMs, 1250); });
Sync("Score durations are not truncated to 1800ms or padded to 60ms", () => { var p = GameMapping.Build(Song(new NoteEvent(60, 0, 4000), new NoteEvent(62, 5000, 25)), new()); Near(p.Notes[0].SoundMs, 4000); Near(p.Notes[1].SoundMs, 25); });
Sync("Catalog distinguishes nine pitched layouts and three unverified drums", () => { Check(InstrumentCatalog.All.Count == 12 && InstrumentCatalog.All.Count(i => i.CanAutoPlay) == 9, "catalog count"); foreach (var i in InstrumentCatalog.All) { Check(i.Keys.Select(k => k.Key).Distinct().Count() == i.Keys.Count, "duplicate instrument key"); Check(i.Keys.All(k => GameMapping.Keys.Contains(k.Key)), "unsafe key"); } });
Sync("Every pitch maps only to selected instrument keys without changing source", () => { foreach (var i in InstrumentCatalog.All.Where(i => i.CanAutoPlay)) for (int pitch = 0; pitch < 128; pitch++) { var song = Song(new NoteEvent(pitch, 0, 150)); var p = GameMapping.Build(song, new() { InstrumentId = i.Id }); Check(p.Notes.Count == 1 && i.Keys.Any(k => k.Key == p.Notes[0].Key && k.Pitches.Contains(p.Notes[0].Pitch)), i.Id + " invalid pitch"); Check(song.Notes[0].Pitch == pitch && song.Notes[0].DurationMs == 150, "mutated source"); } });
Sync("Voice fourteen-key screenshot uses Q/A, not A/Z", () => { var p = GameMapping.Build(Song(new NoteEvent(72, 0, 500), new NoteEvent(60, 750, 250)), new() { InstrumentId = "voice" }); Check(p.Notes.Select(n => n.Key).SequenceEqual(new[] { 'Q', 'A' }), "voice rows"); Check(InstrumentCatalog.Get("voice").Keys.Count == 14, "row count"); });
Sync("Horn fourteen-key actual register is C3-B4", () => { var p = GameMapping.Build(Song(new NoteEvent(60, 0, 100), new NoteEvent(48, 200, 100), new NoteEvent(72, 400, 100)), new() { InstrumentId = "horn" }); Check(p.Notes.Select(n => n.Key).SequenceEqual(new[] { 'Q', 'A', 'Q' }) && p.Report.Folded == 1, "horn mapping"); });
Sync("Old lyre uses per-register altered pitches", () => { var p = GameMapping.Build(Song(new NoteEvent(73, 0, 100), new NoteEvent(63, 200, 100), new NoteEvent(58, 400, 100)), new() { InstrumentId = "vintage" }); Check(p.Notes.Select(n => n.Key).SequenceEqual(new[] { 'W', 'D', 'M' }) && p.Report.Accidentals == 0, "vintage mapping"); Check(GameMapping.Build(Song(new NoteEvent(74, 0, 100)), new() { InstrumentId = "vintage", Accidentals = AccidentalMode.Skip }).Notes.Count == 0, "vintage accidental skip"); });
Sync("Guitar melody can never trigger its chord row", () => { foreach (string id in new[] { "ukulele", "euphonia" }) { var p = GameMapping.Build(Song(Enumerable.Range(0, 128).Select(n => new NoteEvent(n, n * 200, 120)).ToArray()), new() { InstrumentId = id }); Check(p.Notes.All(n => "ASDFGHJZXCVBNM".Contains(n.Key) && n.ChordPitches == null), "single melody triggered native chord"); } });
Sync("Ukulele and Euphonia differ by a measured octave", () => { var song = Song(new NoteEvent(60, 0, 100)); var u = GameMapping.Build(song, new() { InstrumentId = "ukulele" }); var g = GameMapping.Build(song, new() { InstrumentId = "euphonia" }); Check(u.Notes.Single().Key == 'Z' && g.Notes.Single().Key == 'A', "guitar registers collapsed"); });
Sync("Existing guitar C chord becomes a single native Q batch", () => { var song = Song(new NoteEvent(60, 0, 500), new NoteEvent(64, 0, 400), new NoteEvent(67, 0, 600)); var p = GameMapping.Build(song, new() { InstrumentId = "euphonia" }); Check(p.Notes.Single().Key == 'Q' && p.Notes[0].ChordPitches!.SequenceEqual(new[] { 60, 64, 67 }) && p.Report.NativeChords == 1 && p.Report.Simplified == 0, "C recognition"); Near(p.Notes[0].SoundMs, 400); });
Sync("All seven native guitar chords use their own Q-U keys", () => { foreach (var k in InstrumentCatalog.Get("euphonia").Keys.Where(k => k.IsChord)) { var p = GameMapping.Build(Song(k.Pitches.Select(p => new NoteEvent(p, 0, 250)).ToArray()), new() { InstrumentId = "euphonia" }); Check(p.Notes.Single().Key == k.Key && p.Report.NativeChords == 1, "native " + k.Label); } });
Sync("Partial, extra and near-time chords never invent guitar accompaniment", () => { foreach (var notes in new[] { new[] { new NoteEvent(60, 0, 100), new NoteEvent(64, 0, 100) }, new[] { new NoteEvent(60, 0, 100), new NoteEvent(64, 0, 100), new NoteEvent(67, 1, 100) }, new[] { new NoteEvent(60, 0, 100), new NoteEvent(64, 0, 100), new NoteEvent(67, 0, 100), new NoteEvent(69, 0, 100) } }) { var p = GameMapping.Build(Song(notes), new() { InstrumentId = "euphonia" }); Check(p.Report.NativeChords == 0 && p.Notes.All(n => !"QWERTYU".Contains(n.Key)), "invented native chord"); } });
Sync("Native chord can be disabled and never overrides melody-only or arpeggio", () => { var song = Song(new NoteEvent(60, 0, 200), new NoteEvent(64, 0, 200), new NoteEvent(67, 0, 200)); foreach (var o in new[] { new PlayOptions { InstrumentId = "euphonia", NativeGuitarChords = false }, new PlayOptions { InstrumentId = "euphonia", Chords = ChordMode.MelodyOnly }, new PlayOptions { InstrumentId = "euphonia", Chords = ChordMode.Ascending }, new PlayOptions { InstrumentId = "euphonia", MaxChordNotes = 2 } }) Check(GameMapping.Build(song, o).Report.NativeChords == 0, "mode ignored"); });
Sync("Unverified percussion profiles fail closed with readable reason", () => { foreach (var i in InstrumentCatalog.All.Where(i => !i.CanAutoPlay)) { var p = GameMapping.Build(Song(new NoteEvent(60, 0, 100)), new() { InstrumentId = i.Id }); Check(p.Notes.Count == 0 && p.Warnings.Any(w => w.Contains("待核验") || w.Contains("未核验")), "drum emitted melody keys"); } });
Sync("Long/short holds apply to sustaining instruments and scale with speed", () => { var song = Song(new NoteEvent(60, 0, 4000), new NoteEvent(62, 6000, 250)); var p = GameMapping.Build(song, new() { InstrumentId = "harmonic", Speed = 2 }); Near(p.Notes[0].HoldMs, 2000); Near(p.Notes[1].HoldMs, 125); Near(p.Notes[1].StartMs, 3000); Near(p.Notes[0].SoundMs, 2000); });
Sync("Plucked instruments retain score onsets but do not claim sustain", () => { var song = Song(new NoteEvent(60, 0, 4000), new NoteEvent(62, 6000, 250)); var p = GameMapping.Build(song, new() { InstrumentId = "windsong", HoldMs = 65 }); Near(p.Notes[0].HoldMs, 65); Near(p.Notes[0].SoundMs, 4000); Near(p.Notes[1].StartMs, 6000); Check(!p.Notes[0].Sustain, "plucked sustain claim"); var fixedPlan = GameMapping.Build(song, new() { InstrumentId = "harmonic", HoldByScore = false, HoldMs = 70 }); Near(fixedPlan.Notes[0].HoldMs, 70); });
Sync("Sustain releases before repeated-key attack without shifting its onset", () => { var p = GameMapping.Build(Song(new NoteEvent(60, 0, 4000), new NoteEvent(60, 500, 1000)), new() { InstrumentId = "harmonic" }); Near(p.Notes[1].StartMs, 500); Check(p.Notes[0].HoldMs < 500 && p.Notes[0].SoundMs < 500, "sustained overlap"); });
Sync("Legacy options keep loading without a countdown requirement", () => { var p = JsonSerializer.Deserialize<PlayOptions>("{\"countdownSeconds\":0,\"speed\":1}", JsonDefaults.Options)!; p.Validate(); Check(p.InstrumentId == "windsong" && p.HoldByScore && p.NativeGuitarChords, "legacy defaults"); });
Sync("Shortcut starts exactly once immediately after physical key release", () => { var gate = new ShortcutLaunchGate(); var held = new ShortcutState(true, true, true, true, false, true, true); Check(gate.Request(held) == ShortcutDecision.WaitForRelease, "premature start"); Check(gate.Poll(held with { EnterDown = false }) == ShortcutDecision.WaitForRelease, "Shift still down"); Check(gate.Poll(held with { ShiftDown = false, EnterDown = false }) == ShortcutDecision.Start, "no release start"); Check(gate.Poll(held with { ShiftDown = false, EnterDown = false }) == ShortcutDecision.Ignored, "double start"); });
Sync("Shortcut after an already released key does not add a delay", () => { Check(new ShortcutLaunchGate().Request(new(true, true, false, false, false, true, true)) == ShortcutDecision.Start, "countdown introduced"); });
Sync("Shortcut release gate rejects missing consent, focus, stop/start hotkey or extra modifier", () => { var valid = new ShortcutState(true, true, false, false, false, true, true); foreach (var invalid in new[] { valid with { Authorized = false }, valid with { TargetForeground = false }, valid with { OtherModifierDown = true }, valid with { StopRegistered = false }, valid with { StartRegistered = false }, valid with { Busy = true } }) { var gate = new ShortcutLaunchGate(); Check(gate.Request(invalid) == ShortcutDecision.Cancelled && !gate.Pending, "unsafe launch accepted"); } });
Sync("Shortcut wait cancels on focus loss and cannot later resume implicitly", () => { var gate = new ShortcutLaunchGate(); var state = new ShortcutState(true, true, true, true, false, true, true); gate.Request(state); Check(gate.Poll(state with { TargetForeground = false }) == ShortcutDecision.Cancelled, "focus loss ignored"); Check(gate.Poll(state with { ShiftDown = false, EnterDown = false }) == ShortcutDecision.Ignored, "implicit resume"); });
Sync("Emergency stop and score changes cancel pending shortcut", () => { var gate = new ShortcutLaunchGate(); var state = new ShortcutState(true, true, true, true, false, true, true); gate.Request(state); gate.Cancel(); Check(gate.Poll(state with { ShiftDown = false, EnterDown = false }) == ShortcutDecision.Ignored, "F9 cancelled launch restarted"); gate.Request(state); Check(gate.Poll(state with { Authorized = false }) == ShortcutDecision.Cancelled, "score change accepted"); });
Sync("Holding the shortcut never creates repeated start requests", () => { var gate = new ShortcutLaunchGate(); var state = new ShortcutState(true, true, true, true, false, true, true); Check(gate.Request(state) == ShortcutDecision.WaitForRelease, "initial wait"); Check(gate.Request(state) == ShortcutDecision.Ignored, "repeat request accepted"); Check(gate.Poll(state) == ShortcutDecision.WaitForRelease, "held-key timer start"); });
Sync("TXT note durations exactly reflect beats including rests", () => { var s = SongParser.ParseText("BPM=120\nFORMAT=numbered\n1:2 0 2:0.5"); Near(s.Notes[0].DurationMs, 1000); Near(s.Notes[1].StartMs, 1500); Near(s.Notes[1].DurationMs, 250); });
