Sync("Guitar source TXT expands its native chord instead of treating Q as a high melody", () => { var song = SongParser.ParseText("BPM=120\nFORMAT=keys\nINSTRUMENT=euphonia\nQ:2 A Z:0.5"); Check(song.KeyInstrumentId == "euphonia" && song.Notes.Take(3).Select(n => n.Pitch).SequenceEqual(new[] { 60, 64, 67 }), "guitar source Q"); var p = GameMapping.Build(song, new() { InstrumentId = "euphonia" }); Check(p.Notes[0].Key == 'Q' && p.Report.NativeChords == 1, "native round trip"); Near(p.Notes[1].StartMs, 1000); });
Sync("Source fourteen-key TXT rejects keys absent from that instrument", () => { Throws(() => SongParser.ParseText("INSTRUMENT=voice\nFORMAT=keys\nZ")); Throws(() => SongParser.ParseText("INSTRUMENT=djem\nFORMAT=keys\nQ")); });
