Sync("Long synthetic note remains audible late, short note leaves a rest", () => { var p = GameMapping.Build(Song(new NoteEvent(60, 0, 3000), new NoteEvent(62, 4000, 100)), new() { InstrumentId = "harmonic" }); string path = Path.Combine(fixtures, "long-short.wav"); PreviewAudio.WriteWave(p, path); var bytes = File.ReadAllBytes(path); double Energy(int ms) => Enumerable.Range(ms * PreviewAudio.SampleRate / 1000, 1000).Average(i => Math.Abs((double)BitConverter.ToInt16(bytes, 44 + i * 2))); Check(Energy(2000) > 50, "long note inaudible"); Check(Energy(3500) == 0, "rest flattened"); });
Sync("Updated built-ins refresh cached rhythm metadata without losing user settings", () => { string builtin = Path.Combine(fixtures, "refresh-builtins"), data = Path.Combine(fixtures, "refresh-data"); Directory.CreateDirectory(builtin); string path = Path.Combine(builtin, "one.json"); File.WriteAllText(path, SongParser.ToJson(Song(new NoteEvent(60, 0, 1000)))); var store = new LibraryStore(data, builtin); var entry = store.Entries.Single(); entry.Favorite = true; entry.InQueue = true; entry.Options.Speed = 1.5; string id = entry.Id; store.Save(); File.WriteAllText(path, SongParser.ToJson(Song(new NoteEvent(60, 0, 500)))); var restored = new LibraryStore(data, builtin).Entries.Single(); Near(restored.DurationMs, 500); Check(restored.Id == id && restored.Favorite && restored.InQueue && restored.Options.Speed == 1.5, "settings lost on built-in refresh"); });
Sync("Background cover preserves aspect without distortion at wide and narrow viewports", () => { foreach (var size in new[] { (1460d, 940d), (1080d, 720d) }) { var p = BackgroundLayout.Place(1672, 941, size.Item1, size.Item2, WallpaperFit.Cover, .68, .5); Near(p.Width / p.Height, 1672d / 941); Check(p.Width >= size.Item1 - .01 && p.Height >= size.Item2 - .01 && p.X <= 0 && p.Y <= 0 && p.X + p.Width >= size.Item1 - .01 && p.Y + p.Height >= size.Item2 - .01, "uncovered background"); } });
Sync("Background contain preserves a portrait image without cropping", () => { var p = BackgroundLayout.Place(600, 1200, 1460, 940, WallpaperFit.Contain, 0, 1); Near(p.Width, 470); Near(p.Height, 940); Near(p.X, 495); Near(p.Y, 0); });
Sync("Fractional WPF viewport sizes do not invert cover clamp bounds", () =>
{
    foreach (var image in new[] { (1672d, 941d), (1920d, 1144d), (1920d, 675d), (600d, 1200d), (80d, 120d), (120d, 80d), (600d, 400d) })
        foreach (double width in new[] { 1445.3333333333333, 1065.3333333333333, 796.6666666666666, 700.6666666666666, 900.6666666666666, 680.6666666666666, 400.66666666666663 })
            foreach (double height in new[] { 902.6666666666666, 682.6666666666666, 252d })
                foreach (double focus in new[] { 0d, .5d, 1d })
                {
                    var p = BackgroundLayout.Place(image.Item1, image.Item2, width, height, WallpaperFit.Cover, focus, focus);
                    Check(p.X <= .01 && p.Y <= .01 && p.X + p.Width >= width - .01 && p.Y + p.Height >= height - .01, "fractional viewport uncovered");
                }
});
