Sync("Custom background resolver rejects absolute and traversing paths", () => { string root = Path.Combine(fixtures, "theme-paths"); Check(BackgroundLayout.ResolveCustom(root, "backgrounds/test.png") == Path.GetFullPath(Path.Combine(root, "backgrounds", "test.png")), "valid background path"); foreach (string p in new[] { "../outside.png", "backgrounds/../../outside.png", "originals/test.png", "backgrounds/nested/a.png", Path.GetFullPath(Path.Combine(fixtures, "outside.png")) }) Throws(() => BackgroundLayout.ResolveCustom(root, p)); });
Sync("Small text stays readable against brightest wallpaper with minimum panel opacity", () => { var background = new UiRgb(255, 255, 255); var masked = new UiRgb(11, 16, 27).Over(background, .20); var panel = new UiRgb(19, 28, 43).Over(masked, .78); Check(new UiRgb(237, 242, 250).Contrast(panel) >= 4.5 && new UiRgb(185, 198, 217).Contrast(panel) >= 4.5, "insufficient worst-case contrast"); });
Sync("Accent and hero text retain minimum contrast on white wallpaper", () =>
{
    var white = new UiRgb(255, 255, 255); var dark = new UiRgb(11, 16, 27);
    var masked = dark.Over(white, .20); var scrim = dark.Over(masked, 21d / 255);
    var panel = new UiRgb(19, 28, 43).Over(masked, .78);
    var hero = new UiRgb(21, 32, 53).Over(scrim, 176d / 255);
    Check(new UiRgb(184, 184, 184).Contrast(panel) >= 4.5, "accent contrast");
    Check(new UiRgb(185, 198, 217).Contrast(hero) >= 4.5, "hero small text contrast");
    Check(new UiRgb(185, 198, 217).Contrast(dark.Over(scrim, 170d / 255)) >= 4.5, "header contrast");
});
