sealed class Recorder : IKeySink
{
    private readonly object gate = new(); private readonly HashSet<char> held = [];
    public List<List<char>> Batches { get; } = [];
    public bool FailPress { get; set; }
    public int DownCount { get { lock (gate) return Batches.Sum(b => b.Count); } }
    public int HeldCount { get { lock (gate) return held.Count; } }
    public void Press(IReadOnlyList<char> keys) { lock (gate) { Batches.Add(keys.ToList()); foreach (char key in keys) held.Add(key); if (FailPress) throw new Exception("simulated output failure"); } }
    public void Release(IReadOnlyList<char> keys) { lock (gate) foreach (char key in keys) held.Remove(key); }
    public void ReleaseAll() { lock (gate) held.Clear(); }
}
